#[test]
fn test_ccitt_out_too_small() {
    // `out` must already hold the rows: 16 x 2 pixels is four bytes, and three are not enough (status 3).
    let ws: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut crate::port::Buf = &mut crate::port::Buf::new();
    t_zeros(out, 3);
    crate::testport::assert_eq(cc_decode(&crate::testport::hex_blob("f0")[..], 0, 1, -1, 16, 2, 0, out, ws), 3, "a buffer short of the rows");
}
