#[test]
fn test_ccitt_faults() {
    let ws: &mut crate::port::Cells = &mut crate::port::Cells::new();
    t_dec(0, ws, &crate::testport::hex_blob("36")[..], -1, 16, 1, 0, 1, 0, -1, -1, -1, -1, "G4: truncated inside a code");
    t_dec(0, ws, &crate::testport::hex_blob("f0")[..], -1, 16, 5, 0, 1, 0, -1, -1, -1, -1, "G4: four rows of five");
    t_dec(0, ws, &crate::testport::hex_blob("0000")[..], -1, 16, 1, 0, 1, 0, -1, -1, -1, -1, "G4: no such mode");
    t_dec(0, ws, &crate::testport::hex_blob("001001")[..], -1, 16, 1, 0, 1, 0, -1, -1, -1, -1, "G4: EOFB with rows owed");
    t_dec(0, ws, &crate::testport::hex_blob("d9a8")[..], 0, 16, 1, 0, 1, 0, -1, -1, -1, -1, "G3: a run past the width");
    t_dec(0, ws, &crate::testport::hex_blob("001001")[..], 0, 16, 1, 0, 1, 0, -1, -1, -1, -1, "G3: RTC with rows owed");
    t_dec(0, ws, &crate::testport::hex_blob("f0")[..], -1, 0, 1, 0, 1, 0, -1, -1, -1, -1, "no width");
    t_dec(0, ws, &crate::testport::hex_blob("f0")[..], -1, 16, 0, 0, 1, 0, -1, -1, -1, -1, "no rows");
}
